```python
def parse(text):
    sections = {}
    current = None

    for line_number, raw_line in enumerate(text.splitlines(), 1):
        line = raw_line.strip()
        if not line or line.startswith('#'):
            continue

        if line.startswith('['):
            if not line.endswith(']') or '[' in line[1:] or ']' in line[1:-1]:
                raise ValueError(f'Line {line_number}: malformed section header')
            name = line[1:-1].strip()
            if not name:
                raise ValueError(f'Line {line_number}: empty section name')
            current = sections.setdefault(name, {})
            continue

        if '=' not in line:
            raise ValueError(f'Line {line_number}: expected key=value')
        if current is None:
            raise ValueError(f'Line {line_number}: entry before any section')
        key, value = line.split('=', 1)
        key = key.strip()
        if not key:
            raise ValueError(f'Line {line_number}: empty key')
        if key in current:
            raise ValueError(f'Line {line_number}: duplicate key {key!r}')
        current[key] = value.strip()

    return sections
```

A line beginning with `[` is treated as a header; nested or unmatched brackets in a header are rejected. Inline `#` remains literal.

