class Buffer:
    def __init__(self, capacity):
        self._validate(capacity)
        self.data = [None] * capacity
        self.read = 0
        self.size = 0

    @staticmethod
    def _validate(capacity):
        if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity <= 0:
            raise ValueError('capacity must be a positive integer')

    def append(self, value):
        if self.size == len(self.data):
            self.data[self.read] = value
            self.read = (self.read + 1) % len(self.data)
        else:
            self.data[(self.read + self.size) % len(self.data)] = value
            self.size += 1

    def pop(self):
        if not self.size:
            raise IndexError('pop from empty buffer')
        value = self.data[self.read]
        self.data[self.read] = None
        self.read = (self.read + 1) % len(self.data)
        self.size -= 1
        return value

    def snapshot(self):
        return [self.data[(self.read + i) % len(self.data)]
                for i in range(self.size)]

    def resize(self, capacity):
        self._validate(capacity)
        retained = self.snapshot()[-capacity:]
        self.data = retained + [None] * (capacity - len(retained))
        self.read = 0
        self.size = len(retained)


class ListOracle:
    def __init__(self, capacity):
        self._validate(capacity)
        self.capacity = capacity
        self.items = []

    @staticmethod
    def _validate(capacity):
        if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity <= 0:
            raise ValueError('capacity must be a positive integer')

    def append(self, value):
        self.items.append(value)
        if len(self.items) > self.capacity:
            self.items.pop(0)

    def pop(self):
        if not self.items:
            raise IndexError('pop from empty buffer')
        return self.items.pop(0)

    def snapshot(self):
        return self.items.copy()

    def resize(self, capacity):
        self._validate(capacity)
        while len(self.items) > capacity:
            self.items.pop(0)
        self.capacity = capacity


