from collections import deque


def counts(events, width):
    if isinstance(width, bool) or not isinstance(width, int) or width < 0:
        raise ValueError('width must be a nonnegative integer')

    active = deque()
    result = {}
    previous = None

    for timestamp, category in events:
        if isinstance(timestamp, bool) or not isinstance(timestamp, int):
            raise ValueError('timestamps must be integers')
        if previous is not None and timestamp < previous:
            raise ValueError('timestamps must be nondecreasing')
        previous = now = timestamp

        active.append((timestamp, category))
        result[category] = result.get(category, 0) + 1
        while active and active[0][0] <= now - width:
            _, expired_category = active.popleft()
            result[expired_category] -= 1
            if result[expired_category] == 0:
                del result[expired_category]

    return result
```

Each event advances the clock to its timestamp; equal timestamps are allowed. An empty sequence has no clock value and returns `{}`. Categories must be hashable, as they are dictionary keys. The input is read without mutation.

Both functions below return one count mapping per operation. They raise a line-numbered `ValueError` for malformed operations, invalid timestamps, or a backward clock; categories must be hashable. Neither mutates the input.

```python
from collections import deque


def validate_width(width):
    if isinstance(width, bool) or not isinstance(width, int) or width < 0:
        raise ValueError('width must be a nonnegative integer')


def read_op(op, number, clock):
    if not isinstance(op, (tuple, list)) or not op:
        raise ValueError(f'Operation {number}: invalid operation')
    kind = op[0]
    if not ((kind == 'event' and len(op) == 3) or
            (kind == 'query' and len(op) == 2)):
        raise ValueError(f'Operation {number}: invalid operation')
    t = op[1]
    if isinstance(t, bool) or not isinstance(t, int):
        raise ValueError(f'Operation {number}: timestamp must be an integer')
    if clock is not None and t < clock:
        raise ValueError(f'Operation {number}: timestamp precedes clock')
    if kind == 'event':
        try:
            hash(op[2])
        except TypeError as exc:
            raise ValueError(f'Operation {number}: category must be hashable') from exc
    return kind, t


def model(operations, width):
    validate_width(width)
    active, counts, results = deque(), {}, []
    clock = None
    for i, op in enumerate(operations, 1):
        kind, clock = read_op(op, i, clock)
        if kind == 'event':
            category = op[2]
            active.append((clock, category))
            counts[category] = counts.get(category, 0) + 1
        while active and active[0][0] <= clock - width:
            _, category = active.popleft()
            counts[category] -= 1
            if counts[category] == 0:
                del counts[category]
        results.append(counts.copy())
    return results


def history_oracle(operations, width):
    validate_width(width)
    history, results = [], []
    clock = None
    for i, op in enumerate(operations, 1):
        kind, clock = read_op(op, i, clock)
        if kind == 'event':
            history.append((clock, op[2]))
        counts = {}
        for t, category in history:
            if clock - width < t <= clock:
                counts[category] = counts.get(category, 0) + 1
        results.append(counts)
    return results
```

